def _wait_time(failure: "Response | None", attempt: int) -> float:
    """Wait before the attempt after `attempt` (1-based): Retry-After if present, else the backoff."""
    if failure is not None:
        for k, v in failure.headers.items():
            if k.lower() == "retry-after":
                try:
                    return int(str(v).strip())
                except ValueError:
                    break
    return _BACKOFF[attempt - 1]


def _send(transport: Transport, method: str, path: str, headers: dict[str, str], body: dict[str, Any] | None) -> "Response | ConnectionError":
    try:
