def _retryable(r: "Response | ConnectionError") -> bool:
    if isinstance(r, ConnectionError):
        return True
    if r.status in _RETRY_STATUSES or r.status == 429:
        return True
    return r.status == 409 and _error(r).code == "idempotency_in_progress"


def _finish(r: "Response | ConnectionError") -> Any:
    if isinstance(r, ConnectionError):
        raise r
    if r.status not in (200, 201):
        raise _error(r)
    return json.loads(r.body)


