    headers = {"Idempotency-Key": key} if key is not None else {}
    for attempt in range(1, MAX_ATTEMPTS + 1):
        r = _send(transport, method, path, headers, body)
        if attempt == MAX_ATTEMPTS or not _retryable(r):
            return _finish(r)
        transport.sleep(_wait_time(None if isinstance(r, ConnectionError) else r, attempt))
    raise AssertionError("unreachable")


def _key(operation: str, reference: str) -> str:
    return f"pl-{operation}-{hashlib.sha256(reference.encode('utf-8')).hexdigest()[:24]}"


